+const cmd = commands[args[0]];
+if (!cmd) {
+  console.error('usage: delivery-keys.mjs <generate|open> ...');
+  process.exit(2);
+}
+cmd().catch((e) => {
+  console.error(e.message);
+  process.exit(1);
+});
