diff --git a/js/theme.js b/js/theme.js
new file mode 100644
index 0000000..98a606b
--- /dev/null
+++ b/js/theme.js
@@ -0,0 +1,38 @@
+// Initial theme setup. Loaded in <head> with blocking="render" so the stored
+// theme is applied before first paint — and before a cross-document view
+// transition captures the new page — avoiding a light/dark flash mid-animation.
+(() => {
+  const root = document.documentElement;
+  let stored = null;
+  try {
+    stored = localStorage.getItem('theme');
+  } catch {
+    // Storage may be unavailable (privacy mode); fall back to system preference.
+  }
+  const prefersDark = matchMedia('(prefers-color-scheme: dark)').matches;
+  root.dataset.theme = stored === 'dark' || stored === 'light'
+    ? stored
+    : (prefersDark ? 'dark' : 'light');
+
+  // Wire up the toggle button once the DOM is available.
+  document.addEventListener('DOMContentLoaded', () => {
+    const toggle = document.querySelector('.theme-toggle');
+    if (!toggle) return;
+
+    const sync = () => {
+      const dark = root.dataset.theme === 'dark';
+      toggle.setAttribute('aria-pressed', String(dark));
+    };
+    sync();
+
+    toggle.addEventListener('click', () => {
+      root.dataset.theme = root.dataset.theme === 'dark' ? 'light' : 'dark';
+      try {
+        localStorage.setItem('theme', root.dataset.theme);
+      } catch {
+        // Ignore persistence failures.
+      }
+      sync();
+    });
+  });
+})();
