+  background-size: cover;
+  background-position: center;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  color: white;
+  text-align: center;
+  padding: 0 20px;
+}
+
+.hero h1 {
+  font-size: 3rem;
+  margin-bottom: 1rem;
+}
+
+/* Content Sections */
+.container {
+  max-width: 1100px;
+  margin: 40px auto;
+  padding: 0 20px;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+  gap: 20px;
+  margin-top: 20px;
+}
+
+.card {
+  background: white;
+  padding: 20px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+  text-align: center;
+}
+
+.card h3 {
+  margin-bottom: 10px;
+  color: var(--primary);
+}
+
+.btn {
+  display: inline-block;
+  background: var(--primary);
+  color: white;
+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  margin-top: 15px;
+  transition: background 0.3s;
+}
+
+.btn:hover {
+  background: #3e2723;
+}
+
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+/* Dark theme (applied before first paint by the inline theme script) */
+:root[data-theme="dark"] {
+  --primary: #3e2723;
+  --secondary: #2b211e;
+  --accent: #ffb74d;
+  --text: #efebe9;
+  --light: #1b1412;
+}
+
+:root[data-theme="dark"] .card {
+  background: #2b211e;
+}
+
+:root[data-theme="dark"] .card h3 {
+  color: var(--accent);
+}
+
+nav a[aria-current="page"] {
+  color: var(--accent);
+}
+
+.page-intro {
+  text-align: center;
+  max-width: 640px;
+  margin: 0 auto;
+}
+
+.price {
+  font-weight: bold;
+  color: var(--primary);
+  margin-top: 8px;
+}
+
+:root[data-theme="dark"] .price {
+  color: var(--accent);
+}
+
+/* ---------- Cross-document page transitions ---------- */
+@view-transition {
+  navigation: auto;
+}
+
+/* The header persists across pages instead of cross-fading */
+nav {
+  view-transition-name: site-nav;
+}
+
+.hero {
+  view-transition-name: hero;
+}
+
+.hero h1 {
+  view-transition-name: hero-title;
+}
+
+::view-transition-group(*) {
+  animation-duration: 0.35s;
+  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
+}
+
+::view-transition-old(root) {
+  animation: 0.25s cubic-bezier(0.4, 0, 1, 1) both vt-fade-out,
+    0.35s cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-out;
+}
+
+::view-transition-new(root) {
+  animation: 0.3s cubic-bezier(0, 0, 0.2, 1) 0.05s both vt-fade-in,
+    0.35s cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-in;
+}
+
+/* Keep the sticky nav visually static during the transition */
+::view-transition-old(site-nav),
