+    240ms cubic-bezier(0, 0, 0.2, 1) 60ms both vt-fade-in,
+    260ms cubic-bezier(0.4, 0, 0.2, 1) both vt-slide-in-left;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  ::view-transition-group(*),
+  ::view-transition-old(*),
+  ::view-transition-new(*) {
+    animation: none !important;
+  }
+}

