+
+// ---- WebAssembly API -------------------------------------------------------
+// The image can be split into horizontal bands so several Web Workers can each
+// render a slice in parallel. Band rows are in screen order (row 0 = top).
+static int W = 0, H = 0, R0 = 0, R1 = 0, passes = 0;
+static Vec *accum = nullptr;            // running sum of per-pass radiance
+static unsigned char *rgba = nullptr;   // 8-bit output for <canvas> ImageData
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE int sphere_count(){ return NSPHERES; }
+
+EMSCRIPTEN_KEEPALIVE void set_sphere_color(int i, double r, double g, double b){
+  if (i >= 0 && i < NSPHERES) spheres[i].c = Vec(r, g, b);
+}
+
+// Prepare to render screen rows [r0, r1) of a w x h image; clears samples.
+// Returns a pointer to the band's RGBA pixels (w * (r1 - r0) * 4 bytes).
+EMSCRIPTEN_KEEPALIVE unsigned char *setup(int w, int h, int r0, int r1){
+  free(accum); free(rgba);
+  W = w; H = h; R0 = r0; R1 = r1; passes = 0;
+  accum = (Vec *)calloc(W * (R1 - R0), sizeof(Vec));
+  rgba = (unsigned char *)malloc(W * (R1 - R0) * 4);
+  return rgba;
+}
+
+// One progressive pass = 1 sample per 2x2 subpixel (4 spp), exactly as the
+// inner loop of the original main(). Returns the pointer to the RGBA band.
+EMSCRIPTEN_KEEPALIVE unsigned char *render_pass(){
+  int w = W, h = H;
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+  for (int row=R0; row<R1; row++){               // Loop over band rows
+    int y = h-row-1;                             // smallpt's y is bottom-up
+    unsigned short Xi[3]={(unsigned short)passes,(unsigned short)(passes*7919),
+                          (unsigned short)(y*y*y)};
+    for (int x=0; x<w; x++)                      // Loop cols
+      for (int sy=0, i=(row-R0)*w+x; sy<2; sy++) // 2x2 subpixel rows
+        for (int sx=0; sx<2; sx++, r=Vec()){     // 2x2 subpixel cols
+          double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+          Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                  cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+          r = radiance(Ray(cam.o+d*140,d.norm()),0,Xi);
+          // Accumulate unclamped radiance; clamping happens on the running
+          // average in toInt(), like the original clamps its per-subpixel
+          // average. Clamping each single sample would darken the image.
+          accum[i] = accum[i] + r*.25;
+        }
+  }
+  passes++;
+  double inv = 1.0 / passes;
+  for (int i=0, n=w*(R1-R0); i<n; i++){
+    rgba[i*4+0] = toInt(accum[i].x*inv);
+    rgba[i*4+1] = toInt(accum[i].y*inv);
+    rgba[i*4+2] = toInt(accum[i].z*inv);
+    rgba[i*4+3] = 255;
+  }
+  return rgba;
+}
+
+} // extern "C"
