+static int W = 0, H = 0;
+static unsigned char *pixels = nullptr;   // RGBA8, top row first
+static Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+static Vec cx, cy;
+
+extern "C" {
+
+// Allocate an RGBA output buffer of w*h pixels; returns its address in memory.
+EMSCRIPTEN_KEEPALIVE unsigned char *smallpt_init(int w, int h) {
+  W = w; H = h;
+  free(pixels);
+  pixels = (unsigned char *)calloc((size_t)w * h * 4, 1);
+  cx = Vec(w*.5135/h);
+  cy = (cx%cam.d).norm()*.5135;
+  return pixels;
+}
+
+EMSCRIPTEN_KEEPALIVE int smallpt_num_spheres() { return NUM_SPHERES; }
+
+EMSCRIPTEN_KEEPALIVE void smallpt_set_color(int i, double r, double g, double b) {
+  if (i >= 0 && i < NUM_SPHERES) spheres[i].c = Vec(r, g, b);
+}
+
+EMSCRIPTEN_KEEPALIVE void smallpt_reset_colors() {
+  for (int i = 0; i < NUM_SPHERES; i++) spheres[i].c = default_spheres[i].c;
+}
+
+// Render image row y (0 = bottom, as in the original) using `samps` samples per
+// 2x2 subpixel (total spp = 4*samps). `seed` decorrelates noise between runs.
+EMSCRIPTEN_KEEPALIVE void smallpt_render_row(int y, int samps, int seed) {
+  if (!pixels || y < 0 || y >= H) return;
+  int w = W, h = H;
+  unsigned short Xi[3] = {0, (unsigned short)seed, (unsigned short)(y*y*y)};
+  unsigned char *row = pixels + (size_t)(h-y-1) * w * 4;
+  for (int x = 0; x < w; x++) {
+    Vec c, r;
+    for (int sy = 0; sy < 2; sy++)
+      for (int sx = 0; sx < 2; sx++, r = Vec()) {
+        for (int s = 0; s < samps; s++) {
+          double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+          Vec d = cx*(((sx+.5 + dx)/2 + x)/w - .5) +
+                  cy*(((sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+          r = r + radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+        }
+        c = c + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+      }
+    row[x*4+0] = (unsigned char)toInt(c.x);
+    row[x*4+1] = (unsigned char)toInt(c.y);
+    row[x*4+2] = (unsigned char)toInt(c.z);
+    row[x*4+3] = 255;
+  }
+}
