+        typeof env.sig !== 'string' || typeof env.kid !== 'string' || typeof env.alg !== 'string'
+      ) {
+        return { state: 'invalid', title: 'Not a recognised Daily Grind receipt or voucher.' };
+      }
+
+      const key = trustedKeys.get(env.kid);
+      if (!key) {
+        return { state: 'invalid', title: 'Unknown signer — this was not signed by a trusted Daily Grind key.' };
+      }
+      if (key.suite !== env.alg) {
+        return { state: 'invalid', title: 'Algorithm mismatch — the document does not match the signing key.' };
+      }
