+        details.push(['Item', `${data.quantity} × ${data.item}`], ['Total', formatMoney(data.totalCents)]);
+      } else {
+        details.push(['Value', formatMoney(data.amountCents)], ['Recipient', data.recipient], ['Expires', formatDate(data.expiresAt)]);
+      }
+      details.push(['Algorithm', key.suite], ['Signed by key', key.display + (key.active ? ' (current)' : ' (retired)')]);
