+    }
+
+    // ---- UI --------------------------------------------------------------
+    const MENU = {
+      'maple-oat-latte': { name: 'Maple Oat Latte', cents: 525 },
+      'dark-roast-espresso': { name: 'Dark Roast Espresso', cents: 350 },
+      'cold-brew': { name: 'Cold Brew', cents: 475 },
+    };
+    const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+    const dateFmt = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+    const formatMoney = (cents) => money.format(Number(cents) / 100);
+    const formatDate = (iso) => {
+      const t = Date.parse(iso);
+      return Number.isNaN(t) ? String(iso) : dateFmt.format(t);
+    };
+
+    const $ = (id) => document.getElementById(id);
+    const tokenField = $('token');
+    const verdict = $('verdict');
+
+    function renderKey() {
+      $('key-suite').textContent = activeKey.suite + (activeKey.suite === 'ML-DSA-65' ? ' (post-quantum)' : ' (classical)');
+      $('key-fingerprint').textContent = activeKey.display;
+    }
+
+    function showVerdict({ state, title, details = [] }) {
+      verdict.dataset.state = state;
+      const heading = document.createElement('strong');
+      heading.textContent = title;
+      const dl = document.createElement('dl');
+      for (const [term, value] of details) {
+        const dt = document.createElement('dt');
+        const dd = document.createElement('dd');
+        dt.textContent = term;
+        dd.textContent = String(value);
+        dl.append(dt, dd);
+      }
+      verdict.replaceChildren(heading, ...(details.length ? [dl] : []));
+    }
+
+    function clearVerdict() {
+      delete verdict.dataset.state;
+      verdict.replaceChildren();
+    }
+
+    async function withBusy(form, fn) {
+      const buttons = form.querySelectorAll('button');
+      buttons.forEach((b) => (b.disabled = true));
+      try {
+        await fn();
+      } catch (err) {
+        showVerdict({ state: 'invalid', title: `Error: ${err.message}` });
+      } finally {
+        buttons.forEach((b) => (b.disabled = false));
+      }
+    }
+
+    async function issueAndShow(type, data) {
+      tokenField.value = await issue(type, data);
+      clearVerdict();
+      showVerdict(await verify(tokenField.value));
+      tokenField.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
+    }
+
+    $('receipt-form').addEventListener('submit', (e) => {
+      e.preventDefault();
+      const form = e.currentTarget;
+      const fd = new FormData(form);
+      const product = MENU[fd.get('item')];
+      const quantity = Number(fd.get('quantity'));
+      withBusy(form, () =>
+        issueAndShow('receipt', { item: product.name, unitCents: product.cents, quantity, totalCents: product.cents * quantity }),
+      );
+    });
+
+    $('voucher-form').addEventListener('submit', (e) => {
+      e.preventDefault();
+      const form = e.currentTarget;
+      const fd = new FormData(form);
+      const expiresAt = new Date(Date.now() + Number(fd.get('days')) * 86_400_000).toISOString();
+      withBusy(form, () =>
+        issueAndShow('voucher', {
+          code: b64url.encode(crypto.getRandomValues(new Uint8Array(9))).toUpperCase(),
+          amountCents: Math.round(Number(fd.get('amount')) * 100),
+          recipient: String(fd.get('recipient')).trim(),
+          expiresAt,
+        }),
+      );
+    });
+
+    $('verify-form').addEventListener('submit', (e) => {
+      e.preventDefault();
+      withBusy(e.currentTarget, async () => showVerdict(await verify(tokenField.value)));
+    });
+
+    tokenField.addEventListener('input', clearVerdict);
+
+    $('copy-token').addEventListener('click', async () => {
+      if (!tokenField.value) return;
+      try {
+        await navigator.clipboard.writeText(tokenField.value);
+        $('copy-token').textContent = 'Copied!';
+      } catch {
+        tokenField.select();
+        $('copy-token').textContent = 'Press Ctrl+C';
+      }
+      setTimeout(() => ($('copy-token').textContent = 'Copy'), 1500);
+    });
+
+    // Demo: inflate the total / voucher value inside the signed payload and re-verify.
+    $('tamper-token').addEventListener('click', async () => {
