+    /* Seasonal Favorites carousel */
+    .carousel {
+      max-width: 520px;
+      margin: 20px auto 0;
+    }
+
+    .carousel-viewport {
+      overflow: clip;
+      border-radius: 8px;
+    }
+
+    .carousel-viewport .card {
+      box-shadow: none;
+      border: 1px solid var(--secondary);
+    }
+
+    /* Only the visible slide participates in the view transition */
+    .carousel .slide:not([hidden]) {
+      view-transition-name: seasonal-slide;
+    }
+
+    .carousel-controls {
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
+      margin-top: 15px;
+    }
+
+    .carousel-controls[hidden] {
+      display: none;
+    }
+
+    .carousel-controls button {
+      font: inherit;
+      background: var(--primary);
+      color: white;
+      border: 0;
+      border-radius: 5px;
+      padding: 8px 16px;
+      cursor: pointer;
+      transition: background 0.3s;
+    }
+
+    .carousel-controls button:hover {
+      background: #3e2723;
+    }
+
+    .carousel-controls button:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    .carousel-status {
+      font-size: 0.9rem;
+    }
+
+    @keyframes slide-to-left {
+      to { transform: translateX(-100%); }
+    }
+
+    @keyframes slide-from-right {
+      from { transform: translateX(100%); }
+    }
+
+    @keyframes slide-to-right {
+      to { transform: translateX(100%); }
+    }
+
+    @keyframes slide-from-left {
+      from { transform: translateX(-100%); }
+    }
+
+    /* Keep the sliding snapshots inside the slide's box */
+    ::view-transition-group(seasonal-slide) {
+      overflow: clip;
+    }
+
+    @media (prefers-reduced-motion: no-preference) {
+      ::view-transition-group(seasonal-slide),
