+---
+import { Image } from 'astro:assets';
+import type { HTMLAttributes } from 'astro/types';
+
+/**
+ * Responsive article image.
+ * - Local images get a `srcset` (from `widths`) plus a `sizes` hint so the browser
+ *   downloads the smallest candidate that fits the rendered slot.
+ * - Remote images can't be optimized, so they are rendered with intrinsic
+ *   dimensions only (still preventing layout shift).
+ * - `priority` marks the LCP image: eager loading + fetchpriority="high".
+ */
+export interface Props extends Omit<HTMLAttributes<'img'>, 'src' | 'width' | 'height'> {
+    src: ImageMetadata | string;
+    alt: string;
+    width: number;
+    height: number;
+    widths: number[];
+    sizes: string;
+    priority?: boolean;
+    quality?: number;
+}
+
+const { src, alt, width, height, widths, sizes, priority = false, quality, ...attrs } = Astro.props;
+const isRemote = typeof src === 'string';
+// Never request candidates wider than the source image.
+const candidateWidths = isRemote ? [] : widths.filter((w) => w <= src.width);
+if (!isRemote && candidateWidths.length === 0) candidateWidths.push(src.width);
+---
+{isRemote ? (
+    <Image
+        src={src}
+        alt={alt}
+        width={width}
+        height={height}
+        priority={priority}
+        {...attrs}
+    />
+) : (
+    <Image
+        src={src}
+        alt={alt}
+        width={width}
+        height={height}
+        widths={candidateWidths}
+        sizes={sizes}
+        format="webp"
+        quality={quality}
+        priority={priority}
+        {...attrs}
+    />
+)}
