--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,68 @@
+import React, { useEffect, useRef } from 'react';
+
+interface Props {
+  /** id of the element that labels the dialog (usually its heading) */
+  labelledBy: string;
+  onClose: () => void;
+  children: React.ReactNode;
+}
+
+/**
+ * Thin wrapper around the native <dialog> element opened with showModal().
+ * The browser provides the top layer, focus trapping, inert background,
+ * Escape-to-close and focus restoration to the invoking element.
+ * Mount it to open it; it calls onClose when dismissed.
+ */
+export default function Modal({ labelledBy, onClose, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (!dialog.open) dialog.showModal();
+
+    // React does not render the `autofocus` attribute, so move initial focus explicitly.
+    const initialFocus = dialog.querySelector<HTMLElement>('[data-autofocus]');
+    initialFocus?.focus();
+
+    return () => {
+      if (dialog.open) dialog.close();
+    };
+  }, []);
+
+  // Light-dismiss: a click on the ::backdrop is dispatched to the <dialog> itself.
+  const handleClick = (event: React.MouseEvent<HTMLDialogElement>) => {
+    if (event.target === event.currentTarget) {
+      const rect = event.currentTarget.getBoundingClientRect();
+      const inside =
+        event.clientX >= rect.left && event.clientX <= rect.right &&
+        event.clientY >= rect.top && event.clientY <= rect.bottom;
+      if (!inside) event.currentTarget.close();
+    }
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      className="modal"
+      aria-labelledby={labelledBy}
+      onClose={onClose}
+      onClick={handleClick}
+    >
+      <div className="relative">
+        <form method="dialog">
+          <button
+            type="submit"
+            aria-label="Close"
+            className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow-md text-gray-500 hover:text-amber-400 hover:scale-110 transition-transform z-10 focus-visible:outline-2 focus-visible:outline-amber-500"
+          >
+            <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+            </svg>
+          </button>
+        </form>
+        {children}
+      </div>
+    </dialog>
+  );
+}
