+        if (!o) return false;
+        const privateRange = o[0] === 10 ||
+          (o[0] === 172 && o[1] >= 16 && o[1] <= 31) ||
+          (o[0] === 192 && o[1] === 168);
+        return privateRange && o[3] !== 0 && o[3] !== 255;
