+          }
+        }
+
+        async poll() {
+          try {
+            const data = await this.request(this.profile.endpoints.status);
+            if (data) { this.failures = 0; this.updateTelemetry(data); }
+          } catch (err) {
+            this.failures += 1;
+            this.log(err.message, 'err');
+            if (this.failures >= 3) this.disconnect('Lost connection after repeated failures.', true);
