+
+      <form
+        className="space-y-3"
+        onSubmit={(e) => {
+          e.preventDefault();
+          persist('http', httpUrl);
+          connect(httpUrl, 'user');
+        }}
+      >
+        <div>
+          <label htmlFor={httpId} className="mb-1 block text-sm font-medium text-gray-700">
+            Status endpoint (HTTP)
+          </label>
+          <input
+            id={httpId}
+            type="url"
+            inputMode="url"
+            autoComplete="off"
+            spellCheck={false}
+            required
+            value={httpUrl}
