+          if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
+          const items = itemsOf(group);
+          const current = items.indexOf(document.activeElement);
+          if (current < 0) return;
+          const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 :
+            (current + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length;
+          event.preventDefault();
+          event.stopImmediatePropagation();
+          items[next].focus({ preventScroll: true });
+        }, true);
+      });
+    }
+
+    // Keyboard inside menus: each group handles only keys from its own items.
+    document.querySelectorAll('.menu > [focusgroup]').forEach((group) => {
+      const menu = group.parentElement;
+      group.addEventListener('keydown', (event) => {
+        const item = event.target.closest('button, a[href]');
+        if (!item || item.closest('[focusgroup]') !== group) return;
+        switch (event.key) {
+          case 'ArrowRight':
+            if (submenuOf(item)) { event.preventDefault(); openAndEnter(item, 'first'); }
+            break;
+          case 'ArrowLeft':
+            if (parentMenu(menu)) { event.preventDefault(); closeAndRestore(menu); }
+            break;
+          case 'Escape':
+            // Close one level only and restore focus to that level's trigger.
+            event.preventDefault();
+            closeAndRestore(menu);
+            break;
+          case 'Tab':
+            // Leave the menu system: Tab continues from the root trigger.
+            closeAndRestore(rootMenu(menu));
+            break;
+          case ' ':
+            if (item.getAttribute('role') === 'menuitemcheckbox') keepOpenItem = item;
+            break;
+        }
+      });
+    });
+
+    // Pointer: clicking a trigger toggles without moving focus mid-click.
+    document.addEventListener('pointerdown', (event) => {
+      if (event.target.closest?.('button[aria-haspopup="menu"][commandfor]')) event.preventDefault();
+    });
+
+    // Hover follows focus; hovering a submenu trigger previews its submenu after a short delay.
+    document.addEventListener('pointermove', (event) => {
+      if (!canHover.matches) return;
+      const item = event.target.closest?.('.menu [focusgroup] :is(button, a[href])');
+      if (!item || document.activeElement === item) return;
+      const group = item.closest('[focusgroup]');
+      item.focus({ focusVisible: false, preventScroll: true });
+      clearTimeout(hoverTimer);
+      for (const open of [...openMenus]) {
+        if (open.parentElement === group && triggerOf.get(open) !== item && isOpen(open)) open.hidePopover();
+      }
+      const submenu = submenuOf(item);
+      if (submenu && !isOpen(submenu)) {
+        hoverTimer = setTimeout(() => {
+          if (document.activeElement === item) showMenu(submenu, item);
+        }, 150);
+      }
+    });
+
+    // Close every menu when focus lands outside the menu system.
+    document.addEventListener('focusin', (event) => {
+      for (const menu of [...openMenus]) {
+        if (parentMenu(menu) || !isOpen(menu)) continue;
+        if (!menu.contains(event.target) && triggerOf.get(menu) !== event.target) menu.hidePopover();
+      }
+    });
+
+    // Activation: toggle checkable state, emit `menuselect`, then close the whole hierarchy.
+    document.addEventListener('click', (event) => {
+      const item = event.target.closest('.menu [focusgroup] :is(button, a[href])');
+      if (!item || submenuOf(item)) return;
+      const root = rootMenu(item.closest('.menu'));
+      const fromPointer = event.detail > 0;
+      const role = item.getAttribute('role');
+      const checkable = role === 'menuitemcheckbox' || role === 'menuitemradio';
+
+      if (role === 'menuitemcheckbox') {
+        item.setAttribute('aria-checked', String(item.getAttribute('aria-checked') !== 'true'));
+      } else if (role === 'menuitemradio') {
+        item.closest('[role="group"]').querySelectorAll('[role="menuitemradio"]')
+          .forEach((radio) => radio.setAttribute('aria-checked', String(radio === item)));
+      }
+
+      item.dispatchEvent(new CustomEvent('menuselect', { bubbles: true }));
+
+      // Space on a checkbox toggles and stays open (APG).
+      if (keepOpenItem === item) { keepOpenItem = null; return; }
+      keepOpenItem = null;
+      // Let the changed check mark show briefly before closing.
+      setTimeout(() => closeAndRestore(root, { fromPointer }), checkable ? 300 : 0);
+    });
+
+    /* ------------------------------------------------------------------
+     * Ordering behavior for the seasonal cards
+     * ------------------------------------------------------------------ */
+    const toast = document.getElementById('toast');
+    const orderCount = document.getElementById('order-count');
+    let toastTimer;
+
+    function announce(message) {
+      toast.textContent = message;
+      toast.classList.add('is-visible');
+      clearTimeout(toastTimer);
+      toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 3200);
+    }
+
+    function applyRecipe(card) {
+      const recipe = HOUSE_RECIPES[card.dataset.drink];
+      card.querySelectorAll('[data-option]').forEach((item) => {
+        const value = recipe[item.dataset.option];
+        const checked = Array.isArray(value) ? value.includes(item.dataset.value) : value === item.dataset.value;
+        item.setAttribute('aria-checked', String(checked));
+      });
+      renderSelection(card);
+    }
+
+    const labelOf = (item) => item.firstChild.textContent.trim();
+    const checkedIn = (card, option) =>
+      [...card.querySelectorAll(`[data-option="${option}"][aria-checked="true"]`)];
+
+    function describe(card) {
+      const one = (option) => checkedIn(card, option)[0];
+      const parts = [labelOf(one('size')), labelOf(one('temp'))];
+      const milk = one('milk');
+      parts.push(milk.dataset.value === 'none' ? 'no milk' : `${labelOf(milk).toLowerCase()} milk`);
+      const shots = one('shots');
+      if (shots.dataset.value !== 'none') parts.push(`${labelOf(shots).toLowerCase()} shot`);
+      const extras = [...checkedIn(card, 'syrup'), ...checkedIn(card, 'topping')].map((i) => labelOf(i).toLowerCase());
+      if (extras.length) parts.push(`+ ${extras.join(', ')}`);
+      return parts.join(' · ');
+    }
+
+    function renderSelection(card) {
+      card.querySelector('.card-selection').textContent = describe(card);
+    }
+
+    document.querySelectorAll('.card[data-drink]').forEach((card) => {
+      const name = card.querySelector('h3').textContent.trim();
+      applyRecipe(card);
+      card.addEventListener('menuselect', async (event) => {
+        const item = event.target;
+        if (item.dataset.option) return renderSelection(card);
+        switch (item.dataset.action) {
+          case 'add': {
+            orderCount.textContent = String(Number(orderCount.textContent) + 1);
+            announce(`Added ${name} (${describe(card)}) to your order.`);
+            break;
+          }
+          case 'reset':
+            applyRecipe(card);
+            announce(`${name} reset to the house recipe.`);
+            break;
+          case 'favorite':
+            announce(item.getAttribute('aria-checked') === 'true'
+              ? `${name} saved to your favorites.` : `${name} removed from your favorites.`);
+            break;
+          case 'copy-link': {
+            const url = card.querySelector('[data-link="details"]').href;
+            try {
+              await navigator.clipboard.writeText(url);
+              announce(`Link to ${name} copied.`);
+            } catch {
+              announce(`Couldn't copy the link. ${url}`);
+            }
+            break;
+          }
+        }
+      });
+    });
+  </script>
+
 </body>

