@@ -0,0 +1,46 @@
+// Minimal service worker: makes the app installable/offline-capable without
+// ever pinning a stale page. All requests are network-first (cache is an offline fallback) so that changes to
+// the migration logic (and the legacy -> new redirect) always take effect.
+const CACHE = 'dg-v2';
+const PRECACHE = [
+  '/',
+  '/js/origins.js',
+  '/js/app.js',
+  '/js/prefs.js',
+  '/js/migration.js',
+  '/icons/icon-192.png',
+  '/icons/icon-512.png',
+];
+
+self.addEventListener('install', (event) => {
+  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
+});
+
+self.addEventListener('activate', (event) => {
+  event.waitUntil(
+    caches.keys()
+      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
+      .then(() => self.clients.claim()),
+  );
+});
+
+self.addEventListener('fetch', (event) => {
+  const req = event.request;
+  const url = new URL(req.url);
+  if (req.method !== 'GET' || url.origin !== self.location.origin) return;
+  // Manifests and the association file must always be fresh for the browser's
+  // migration checks.
+  if (url.pathname.endsWith('.webmanifest') || url.pathname.startsWith('/.well-known/')) return;
+
+  event.respondWith(
+    fetch(req)
+      .then((res) => {
+        if (res.ok && req.mode !== 'navigate') {
+          const copy = res.clone();
+          caches.open(CACHE).then((c) => c.put(req, copy));
+        }
+        return res;
+      })
+      .catch(() => caches.match(req).then((hit) => hit || (req.mode === 'navigate' ? caches.match('/') : Response.error()))),
+  );
+});

