+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getRpId } from '../../../../lib/auth/config';
+import { error, json } from '../../../../lib/auth/http';
+import { getCurrentUser } from '../../../../lib/auth/session';
+import { findCredentialsByUserId } from '../../../../lib/auth/store';
+
+/** Step-up options restricted to the signed-in user's own passkeys. */
+export const POST: APIRoute = async ({ session, url }) => {
+  const user = await getCurrentUser(session);
+  if (!user) return error('Not signed in.', 401, 'unauthenticated');
+
+  const credentials = await findCredentialsByUserId(user.passkeyUserId);
+  if (credentials.length === 0) return error('No passkeys registered.', 409, 'no_passkeys');
+
+  const userVerification = 'preferred' as const;
+  const options = await generateAuthenticationOptions({
+    rpID: getRpId(url),
+    allowCredentials: credentials.map((c) => ({ id: c.id, transports: c.transports })),
+    userVerification,
+  });
+
+  session!.set('pendingReauth', { challenge: options.challenge, userVerification });
+  return json(options);
+};
