+/// <reference types="astro/client" />
+
+declare namespace App {
+  interface SessionData {
+    readingList: string[];
+    /** The signed-in account, if any. */
+    user: { id: string; username: string };
+    /** Epoch ms of the last strong authentication (sign-in or reauthentication). */
+    authAt: number;
+    /** Outstanding WebAuthn challenge for this browser session. */
+    webauthnChallenge: {
+      value: string;
+      purpose: 'register' | 'login' | 'reauth';
+      expiresAt: number;
+      /** For passkey-first sign-up: the account to create once registration verifies. */
+      pendingUser?: { username: string; webauthnUserID: string };
+      /** Registration started via conditional create (automatic passkey upgrade). */
+      conditional?: boolean;
+    };
+  }
+}
