+---
+import Layout from '../layouts/Layout.astro';
+import AccountSettings from '../components/AccountSettings';
+import { currentUser, publicPasskey, publicUser, relyingParty } from '../lib/auth/server';
+import { listPasskeys } from '../lib/auth/store';
+
+const user = await currentUser(Astro);
+if (!user) {
+  const next = `${import.meta.env.BASE_URL.replace(/\/?$/, '/')}account`;
+  return Astro.redirect(`${import.meta.env.BASE_URL.replace(/\/?$/, '/')}signin?next=${encodeURIComponent(next)}`);
+}
+Astro.response.headers.set('Cache-Control', 'no-store');
+const passkeys = (await listPasskeys(user.id)).map(publicPasskey);
+const { rpID } = relyingParty(Astro);
+---
+
+<Layout title="Account settings | The DevTools Times">
+  <div class="py-12 px-4 sm:px-6 lg:px-8">
+    <AccountSettings client:load initialUser={publicUser(user)} initialPasskeys={passkeys} rpID={rpID} />
+  </div>
+</Layout>
