--- /dev/null
+++ b/src/pages/api/auth/logout.ts
@@ -0,0 +1,13 @@
+import type { APIRoute } from 'astro';
+import { json } from '../../../lib/auth/server';
+
+export const POST: APIRoute = async ({ session }) => {
+  if (session) {
+    // Rotate the session ID but keep non-auth data such as the reading list.
+    await session.regenerate();
+    session.delete('user');
+    session.delete('authAt');
+    session.delete('webauthnChallenge');
+  }
+  return json({ ok: true });
+};
