+    (function () {
+      var nav = document.querySelector('nav');
+      var links = Array.prototype.slice.call(document.querySelectorAll('nav a.nav-section'));
+      var sections = links
+        .map(function (link) { return document.querySelector(link.getAttribute('href')); })
+        .filter(Boolean);
+
+      function navHeight() {
+        return nav.getBoundingClientRect().height;
+      }
+
+      function setActive(id) {
+        links.forEach(function (link) {
+          var isActive = link.getAttribute('href') === '#' + id;
+          link.classList.toggle('active', isActive);
+          if (isActive) {
+            link.setAttribute('aria-current', 'location');
+          } else {
+            link.removeAttribute('aria-current');
+          }
+        });
+      }
+
+      function update() {
+        var offset = navHeight();
+        document.documentElement.style.setProperty('--nav-height', offset + 'px');
+
+        // The section whose top has passed a line just below the sticky nav is "current".
+        var marker = offset + window.innerHeight * 0.25;
+        var current = null;
+        sections.forEach(function (section) {
+          if (section.getBoundingClientRect().top <= marker) current = section.id;
+        });
+
+        // At the very bottom of the page, highlight the last section even if it's short.
+        var scrolledToBottom =
+          window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2;
+        if (scrolledToBottom && sections.length) current = sections[sections.length - 1].id;
+
+        setActive(current);
+      }
+
+      var ticking = false;
+      function onScroll() {
+        if (ticking) return;
+        ticking = true;
+        window.requestAnimationFrame(function () {
+          ticking = false;
+          update();
+        });
+      }
+
+      window.addEventListener('scroll', onScroll, { passive: true });
+      window.addEventListener('resize', onScroll);
+      window.addEventListener('load', update);
+      update();
+    })();
