+      var ALLOWED_EXTERNAL_HOSTS = ['instagram.com', 'facebook.com'];
+      var SAFE_PROTOCOLS = ['https:', 'http:'];
+
+      // ---- URL helpers (always parse with URL, never split strings) -------
+      function parseUrl(raw) {
+        if (typeof raw !== 'string' || raw.length === 0 || raw.length > 2048) return null;
+        // Reject control characters / whitespace tricks that browsers strip.
+        if (/[\u0000-\u001F\u007F\s\\]/.test(raw)) return null;
+        try {
+          return new URL(raw, window.location.href);
+        } catch (e) {
+          return null;
+        }
+      }
+
+      // True if `host` equals `domain` or is a subdomain of it (label-aligned).
+      function hostMatchesDomain(host, domain) {
+        host = host.toLowerCase().replace(/\.$/, '');
+        domain = domain.toLowerCase();
+        return host === domain || host.endsWith('.' + domain);
+      }
+
+      function isSameSiteUrl(url) {
+        if (!url || SAFE_PROTOCOLS.indexOf(url.protocol) === -1) return false;
+        if (url.username || url.password) return false;
+        if (url.origin === window.location.origin) return true;
+        return url.protocol === 'https:' && hostMatchesDomain(url.hostname, SITE_DOMAIN);
+      }
+
+      function isAllowedExternalUrl(url) {
+        if (!url || url.protocol !== 'https:') return false;
+        if (url.username || url.password) return false;
+        return ALLOWED_EXTERNAL_HOSTS.some(function (d) {
+          return hostMatchesDomain(url.hostname, d);
+        });
+      }
+
+      // Returns a safe absolute href for a same-site redirect, or null.
+      function validateRedirect(raw) {
+        var url = parseUrl(raw);
+        return isSameSiteUrl(url) ? url.href : null;
+      }
+
+      function safeRedirect(raw) {
+        var target = validateRedirect(raw);
+        if (target) {
+          window.location.assign(target);
+        } else {
+          console.warn('[DailyGrind] Blocked redirect to untrusted URL:', raw);
+        }
+      }
+
+      // ---- External link hardening ---------------------------------------
+      function hardenLinks() {
+        var links = document.querySelectorAll('a[href]');
+        Array.prototype.forEach.call(links, function (a) {
+          var url = parseUrl(a.getAttribute('href'));
+          if (isSameSiteUrl(url)) {
+            if (url.origin !== window.location.origin) a.setAttribute('rel', 'noopener');
+            return;
+          }
+          if (isAllowedExternalUrl(url)) {
+            a.href = url.href;
+            a.target = '_blank';
+            a.setAttribute('rel', 'noopener noreferrer external');
+            return;
+          }
+          // Unknown host or dangerous scheme (javascript:, data:, ...): neutralise.
+          a.removeAttribute('href');
+          a.classList.add('link-blocked');
+          a.setAttribute('aria-disabled', 'true');
+          a.title = 'Link blocked: untrusted destination';
+        });
+      }
+
+      // ---- UI helpers ----------------------------------------------------
+      var statusEl = document.getElementById('order-status');
+      var pointsEl = document.getElementById('widget-points');
+
+      function showStatus(text) {
+        statusEl.textContent = text; // textContent only: never inject HTML
+        statusEl.classList.add('visible');
+      }
+
+      var ORDER_STATES = {
+        received: 'Order received — we are on it!',
+        brewing: 'Your order is brewing…',
+        ready: 'Your order is ready for pickup!',
+        cancelled: 'Your order was cancelled.'
+      };
+
+      // ---- Trusted ordering window ---------------------------------------
+      var orderWindow = null;
+
+      document.getElementById('order-now').addEventListener('click', function (e) {
+        e.preventDefault();
+        orderWindow = window.open(TRUSTED_ORDER_ORIGIN + '/', 'dailygrind-order', 'width=480,height=720');
+        if (!orderWindow) safeRedirect(this.getAttribute('href'));
+      });
+
+      function handleOrderMessage(data) {
+        switch (data.type) {
+          case 'order-status':
+            if (Object.prototype.hasOwnProperty.call(ORDER_STATES, data.status)) {
+              var label = ORDER_STATES[data.status];
+              if (typeof data.orderId === 'string' && /^[A-Za-z0-9-]{1,32}$/.test(data.orderId)) {
+                label += ' (Order #' + data.orderId + ')';
+              }
+              showStatus(label);
+            }
+            break;
+          case 'redirect':
+            safeRedirect(data.url);
+            break;
+        }
+      }
+
+      // ---- Sandboxed rewards widget (opaque "null" origin) ----------------
+      var widgetFrame = document.getElementById('rewards-widget');
+      var pinnedWidgetSource = null;
+
+      function handleWidgetMessage(event) {
+        var data = event.data;
+        if (pinnedWidgetSource === null) {
+          // Pin only on the init handshake, and only if it really comes from
+          // our own iframe's browsing context.
+          if (data.type !== 'widget-init') return false;
+          if (!widgetFrame || event.source !== widgetFrame.contentWindow) return false;
+          pinnedWidgetSource = event.source;
+          pointsEl.textContent = '0 / 10 stamps';
+          return true;
+        }
+        // After pinning: accept only the exact same window object.
+        if (event.source !== pinnedWidgetSource) return false;
+        switch (data.type) {
+          case 'widget-init':
+            pointsEl.textContent = '0 / 10 stamps';
+            break;
+          case 'widget-points':
+            var stamps = Number(data.stamps), goal = Number(data.goal);
+            if (Number.isInteger(stamps) && Number.isInteger(goal) && goal > 0 && stamps >= 0 && stamps <= goal) {
+              pointsEl.textContent = stamps + ' / ' + goal + ' stamps' + (stamps === goal ? ' — free drink unlocked!' : '');
+            }
+            break;
+          case 'widget-redeem':
+            pointsEl.textContent = 'Enjoy your free drink! ☕';
+            break;
+        }
+        return true;
+      }
+
+      // ---- Single message dispatcher -------------------------------------
+      window.addEventListener('message', function (event) {
+        var data = event.data;
+        if (!data || typeof data !== 'object' || typeof data.type !== 'string') return;
+
+        // Exact origin comparison — no indexOf/startsWith/endsWith on origins.
+        if (event.origin === TRUSTED_ORDER_ORIGIN) {
+          handleOrderMessage(data);
+          return;
+        }
+
+        // Sandboxed iframes without allow-same-origin report origin "null".
+        // Origin alone cannot distinguish them, so identity is pinned by source.
+        if (event.origin === 'null') {
+          if (!handleWidgetMessage(event)) {
+            console.warn('[DailyGrind] Rejected message from unrecognised sandboxed frame.');
+          }
+          return;
+        }
+
+        console.warn('[DailyGrind] Rejected message from untrusted origin:', event.origin);
+      });
+
+      // ---- Same-site ?next= redirect support ------------------------------
+      var next = new URLSearchParams(window.location.search).get('next');
+      if (next !== null) safeRedirect(next);
+
+      hardenLinks();
+
+      // Expose validators for other scripts / tests.
+      window.DailyGrindSecurity = Object.freeze({
+        validateRedirect: validateRedirect,
+        isSameSiteUrl: function (raw) { return isSameSiteUrl(parseUrl(raw)); },
+        isAllowedExternalUrl: function (raw) { return isAllowedExternalUrl(parseUrl(raw)); }
+      });
+    })();
+  </script>
+
 </body>

 </html>

