+        const name = `link-${i}`;
+        if (link.slot !== name) link.slot = name;
+        const li = document.createElement('li');
+        const slot = document.createElement('slot');
+        slot.name = name;
+        li.append(slot);
+        return li;
+      }),
+    );
+  }
